263	<script>
264	const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
265	let mode="released", busy=false;
266	const label={normal:"Ask normally",cut:"Cut the connection",agent:"Crash the agent"};
267	
268	$$("#toggle button").forEach(b=>b.onclick=()=>{ if(busy)return; mode=b.dataset.mode;
269	  $$("#toggle button").forEach(x=>{x.classList.toggle("sel",x===b);x.setAttribute("aria-checked",x===b)});
270	  $("#toggle").classList.toggle("fixed",mode==="fixed"); });
271	
272	function setRO(id,cls,val,sub){const el=$(id);el.className="ro "+cls;const v=el.querySelector(".val");v.textContent=val;v.classList.remove("flip");void v.offsetWidth;v.classList.add("flip");if(sub!==undefined)el.querySelector(".sub").textContent=sub;}
273	function step(s){const order=["calling","witness","reading","done"];const i=order.indexOf(s);$$("#steps .st").forEach((e,j)=>{e.className="st"+(j<i?" done":j===i?" act":"")});if(s==="done")$$("#steps .st").forEach(e=>e.className="st done");}
274	function annun(state,why){const a=$("#annun");a.className="annun"+(state==="on"?" on":state==="agree"?" agree":"");$("#lamp").textContent=state==="agree"?"AGREE":"DISAGREE";$("#why").textContent=why;}
275	function bot(html,crash){const m=$("#botMsg");m.className="bubble bot"+(crash?" crash":"");m.innerHTML=html;m.style.animation="none";void m.offsetWidth;m.style.animation="";}
276	const wire=$("#wire");
277	
278	$$(".go").forEach(b=>b.onclick=()=>run(b.dataset.break,b));
279	
280	async function run(brk,btn){
281	  if(busy)return; busy=true; $("#msg").textContent="";
282	  $$(".go").forEach(x=>x.disabled=true); btn.classList.add("running");
283	  setRO("#roReal","wait","…","Asking Claude through neatlogs' model key");
284	  setRO("#roRec","wait","…","Waiting for neatlogs");
285	  annun("off","Watching the wire…"); step("calling");
286	  $("#recList").innerHTML='<div class="note">Waiting for the run…</div>'; $("#recLink").textContent="";
287	  bot('<span class="typing"><span></span><span></span><span></span></span>');
288	  wire.className="wire on";
289	  try{
290	    const r=await fetch("/api/run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({break:brk,mode})});
291	    const j=await r.json(); if(!r.ok) throw new Error(j.error||"Try again in a moment.");
292	    let job, shownResult=false;
293	    for(let i=0;i<70;i++){
294	      await new Promise(z=>setTimeout(z,1500));
295	      job=await (await fetch("/api/job/"+j.id)).json();
296	      if(job.stage==="failed") throw new Error(job.error||"The run failed.");
297	      if(job.result && !shownResult){ shownResult=true; showResult(brk,job.result); step("reading"); setRO("#roRec","wait","…","neatlogs is storing the record"); }
298	      if(job.stage==="done"){ showRecord(job.record, job.result); break; }
299	    }
300	    if(!job || job.stage!=="done") throw new Error("neatlogs is slow to store the record right now.");
301	  }catch(e){ $("#msg").textContent=e.message; wire.className="wire"; setRO("#roReal","idle","—","Waiting for your click"); setRO("#roRec","idle","—","Read back from neatlogs"); annun("off","The light turns on when the record says the opposite of what really happened."); step(""); bot("Pick a button below to send it."); }
302	  finally{ busy=false; $$(".go").forEach(x=>{x.disabled=false;x.classList.remove("running")}); refreshStats(); }
303	}
304	
305	function showResult(brk,res){
306	  step("witness");
307	  const crashed=res.really==="crashed";
308	  if(brk==="cut"){ wire.className="wire cut"; } else if(brk==="agent"){ wire.className="wire cut"; } else { wire.className="wire"; }
309	  if(crashed){
310	    bot(brk==="cut"?"⚠️ The reply stopped halfway: the connection was cut. I couldn't finish.":"⚠️ My agent run failed: the AI server refused the request.",true);
311	    setRO("#roReal","bad","CRASHED",(brk==="cut"?"Connection cut mid-reply":"Agent run failed")+" · app saw "+res.app);
312	  } else {
313	    bot(String(res.app||"Your refund lookup is ready.").replace(/[<>&#*]/g,"").trim());
314	    setRO("#roReal","ok","OK","The bot answered normally");
315	  }
316	  const d=res.disagreements||[];
317	  if(d.length){ annun("on","Witness: neatlogs' "+(d[0].field==="run_status"?"agent workflow":"AI step")+" says "+nice(d[0].record)+", but the run really "+(crashed?"crashed":"failed")+"."); }
318	  else { annun("agree",crashed?"The record says the run failed. It matches what really happened.":"Nothing broke, and the record says so."); }
319	}
320	function nice(s){return s==="OK"||s==="SUCCESS"?"SUCCESS":s}
321	
322	function showRecord(rec,res){
323	  step("done");
324	  const crashed=res.really==="crashed";
325	  if(!rec){ setRO("#roRec","idle","?","neatlogs had not stored it yet"); return; }
326	  const steps=rec.steps||[];
327	  const main=steps.find(s=>s.name==="Agent workflow"&&s.status==="ERROR")||steps.find(s=>s.name==="Agent workflow")||steps.find(s=>(s.type||"").toLowerCase()==="llm"||/claude|haiku|response/i.test(s.name||""))||steps[0];
328	  const st=main?main.status:rec.status;
329	  const lie=crashed && st!=="ERROR";
330	  setRO("#roRec",lie?"bad":(crashed?"ok":"ok"),st||"?",(main?main.name+" · ":"")+"trace "+(rec.trace_id||"").slice(0,8));
331	  $("#recList").innerHTML="";
332	  steps.forEach((s,i)=>{const row=document.createElement("div");row.className="rec"+(s.name==="TRACE DISAGREE"?" disagree":"");row.style.animationDelay=(i*90)+"ms";
333	    row.innerHTML='<span>'+(s.name==="TRACE DISAGREE"?"🔴 ":"")+(s.name||"step").replace(/[<>&]/g,"")+'</span><span class="chip '+(s.name==="TRACE DISAGREE"?"ERROR":(s.status||"UNSET"))+'">'+(s.name==="TRACE DISAGREE"?"WITNESS":(s.status||"UNSET"))+'</span>';
334	    $("#recList").appendChild(row);});
335	  $("#recLink").innerHTML='Trace <code>'+rec.trace_id+'</code> in the Trueup neatlogs project (neatlogs login to the project needed to open it).';
336	}
337	
338	async function refreshStats(){
339	  try{const s=await (await fetch("/api/stats")).json(); $("#today").textContent=s.today+" / "+s.cap;
340	    const t=s.totals||{}; const cell=(m,b)=>t[m+":"+b]||{runs:0,lit:0};
341	    const rows=[["cut","Cut the connection"],["agent","Crash the agent"],["normal","Ask normally"]];
342	    $("#tally").innerHTML=rows.map(([b,n])=>{const r=cell("released",b),f=cell("fixed",b);
343	      return '<div class="proof"><div class="label">'+n+'</div><div style="display:flex;gap:18px;flex-wrap:wrap"><div><div class="big" style="font-size:2rem"><span class="'+(r.lit?'r':'')+'">'+r.lit+'</span><span style="color:var(--dim);font-size:1.2rem"> / '+r.runs+'</span></div><p>light on · as released</p></div><div><div class="big" style="font-size:2rem;color:var(--green)">'+f.lit+'<span style="color:var(--dim);font-size:1.2rem"> / '+f.runs+'</span></div><p>light on · with fixes</p></div></div></div>'}).join("");
344	  }catch(e){}
345	}
346	refreshStats(); setInterval(refreshStats,15000);
347	
348	$("#copy").onclick=()=>{navigator.clipboard&&navigator.clipboard.writeText("import trueup.witness\ntrueup.witness.watch()");$("#copy").textContent="Copied";setTimeout(()=>$("#copy").textContent="Copy",1500)};
349	
350	const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");if(e.target.querySelector("#c1"))count();io.unobserve(e.target)}}),{threshold:.15});
351	$$(".reveal").forEach(e=>io.observe(e));
352	let counted=false;function count(){if(counted)return;counted=true;const a=$("#c1"),b=$("#c2");const t0=performance.now();
353	  (function f(t){const p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);a.textContent=(6.2*e).toFixed(1);b.textContent=(11.1*e).toFixed(1);if(p<1)requestAnimationFrame(f)})(t0);}
354	</script>
